#!/usr/bin/env python3
"""Emit a bounded, idempotent existing-node sheet refinement; no Figma calls."""
from pathlib import Path
import json,argparse,hashlib
p=argparse.ArgumentParser();p.add_argument('--ids',default='all');args=p.parse_args();here=Path(__file__).resolve().parent;root=here.parent;state=json.loads((here/'state.json').read_text());data={s['id']:s for s in json.loads((root/'data/current-all.json').read_text())};scope=json.loads((root/'data/p2p3-visual-scope.json').read_text());requested=scope if args.ids=='all'else args.ids.split(',');ids=[id for id in requested if id in state['completed']];targets=[{'nodeId':state['screens'][id],'data':{k:data[id][k]for k in ['id','layout','kitchen']if k in data[id]}}for id in ids]
source=(root/'figma-plugin/p2p3-visual-fixes.js').read_text().split('const P2P3_VISUAL_PREVIOUS_BUILD')[0]
context={'pageId':state['pageId'],'surfaceVariable':state['variables'].get('color/surface'),'surface':json.loads((root/'data/tokens.json').read_text())['colors']['surface'],'targets':targets}
code='const INPUT='+json.dumps(context,separators=(',',':'))+';\n'+source+'''
const page=await figma.getNodeByIdAsync(INPUT.pageId);await figma.setCurrentPageAsync(page);const surfaceVariable=INPUT.surfaceVariable?await figma.variables.getVariableByIdAsync(INPUT.surfaceVariable):null;
function fill(n){const hex=INPUT.surface;let paint={type:'SOLID',color:{r:parseInt(hex.slice(1,3),16)/255,g:parseInt(hex.slice(3,5),16)/255,b:parseInt(hex.slice(5,7),16)/255}};if(surfaceVariable)paint=figma.variables.setBoundVariableForPaint(paint,'color',surfaceVariable);n.fills=[paint];}
const work=[],fonts=new Map();for(const item of INPUT.targets){const node=await figma.getNodeByIdAsync(item.nodeId);if(!node||!node.name.startsWith(item.data.id+' ·'))throw Error('Wrong target '+item.nodeId);work.push({...item,node});for(const text of node.findAllWithCriteria({types:['TEXT']}))for(const part of text.getStyledTextSegments(['fontName']))fonts.set(JSON.stringify(part.fontName),part.fontName);}await Promise.all([...fonts.values()].map(f=>figma.loadFontAsync(f)));
const reactions=new Map();for(const {node}of work)for(const n of node.findAll(()=>true))if('reactions'in n&&n.reactions.length)reactions.set(n.id,JSON.stringify(n.reactions));
const results=work.map(({node,data})=>p2p3VisualRefine(node,data)),reactionErrors=[];for(const [id,prior]of reactions){const n=await figma.getNodeByIdAsync(id);if(!n||JSON.stringify(n.reactions)!==prior)reactionErrors.push(id);}const mutated=results.flatMap(r=>r.changedNodeIds||[]);const applied=results.filter(r=>r.applied),dimensions=applied.map(r=>[r.id,r.before.panelTop,r.after.panelTop,r.after.viewportHeight,r.after.bodyHeight,r.after.scrolls]);const wrongGaps=applied.filter(r=>Math.abs(r.footerGap-12)>0.1).map(r=>({id:r.id,gap:r.footerGap}));return {kind:'p2p3-compact-sheet',createdNodeIds:[],mutatedNodeIds:[...new Set(mutated)],targetColumns:['id','oldTop','newTop','viewportHeight','bodyHeight','scrolls'],targets:dimensions,skipped:results.filter(r=>!r.applied).map(r=>({id:r.id,reason:r.reason})),checks:{applied:dimensions.length,reactionsPreserved:reactions.size,reactionErrors,wrongGaps,screenIdsPreserved:true}};
'''
name='all'if args.ids=='all'else'benchmark';out=here/f'p2p3-visual-{name}.js';out.write_text(code);assert len(code)<48000;print(json.dumps({'file':str(out),'characters':len(code),'targets':len(targets),'sha256':hashlib.sha256(code.encode()).hexdigest()}))
